   714  /* Find the index of the first out-of-order element in @data, assuming that
   715   * @data is an array of elements of given @type, starting at index @start and
   716   * containing a further @len-@start elements. */
   717  #define DEFINE_FIND_UNORDERED(type) \
   718    static gsize \
   719    find_unordered_##type (const guint8 *data, gsize start, gsize len) \
   720    { \
   721      gsize off; \
   722      type current, previous; \
   723      \
   724      memcpy (&previous, data + start * sizeof (current), sizeof (current)); \
   725      for (off = (start + 1) * sizeof (current); off < len * sizeof (current); off += sizeof (current)) \
   726        { \
   727          memcpy (&current, data + off, sizeof (current)); \
   728          if (current < previous) \
   729            break; \
   730          previous = current; \
   731        } \
   732      return off / sizeof (current) - 1; \
   733    }
